    {
      "rank": 1,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Twisted bilayer graphene revealed that moiré materials can host tunable flat bands, correlated insulating states and superconductivity. It opened a broad, experimentally productive field in quantum materials.",
        "attribution": "Bistritzer and MacDonald established the theoretical flat-band framework; Jarillo-Herrero's group demonstrated the central correlated states. Andrei's work also made major contributions to experimental study and confirmation.",
        "maturity": "The discovery has been reproduced and extended across moiré systems, though the precise mechanisms and range of phases remain active research.",
        "uncertainties": [
          "The microscopic origin of superconductivity and the relative importance of different correlated phases remain unsettled."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made a major advance in the quantitative treatment of strongly correlated electrons and has become a central framework for understanding materials such as transition-metal oxides.",
        "attribution": "Georges, Kotliar and Vollhardt were central to developing and establishing the method and its physical interpretation.",
        "maturity": "The framework has decades of theoretical development and extensive use alongside experiment, with extensions addressing its limits.",
        "uncertainties": [
          "Its local approximation captures important physics but does not by itself resolve all spatial correlations in real materials."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and experimental realization of topological insulators and the quantum spin Hall effect established a new class of matter with robust, symmetry-protected boundary states.",
        "attribution": "Kane and Mele provided foundational theory; Molenkamp's group supplied a landmark experimental realization of the quantum spin Hall state.",
        "maturity": "The basic phenomena are well established, with extensive theoretical and experimental follow-up across materials.",
        "uncertainties": [
          "The proposed credit spans a broad field, and the relative weight of the quantum spin Hall discovery versus later topological-insulator work needs careful delimitation."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Roderich Moessner",
        "Shivaji L. Sondhi",
        "Steven T. Bramwell"
      ],
      "assessment": {
        "nobel_worthiness": "Spin ice provided a compelling material realization of frustration and emergent magnetic-monopole-like excitations, linking microscopic spin constraints to striking collective behavior.",
        "attribution": "Bramwell's experiments established key thermodynamic and magnetic signatures; Moessner and Sondhi helped develop the theoretical understanding of the emergent excitations.",
        "maturity": "The spin-ice phenomenology is well studied and supported by multiple measurements, although the monopoles are emergent quasiparticles rather than freely propagating fundamental particles.",
        "uncertainties": [
          "The phrase 'magnetic monopoles' can overstate the analogy if the emergent, constrained nature of the excitations is not made explicit."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics joined superconducting circuits to cavity quantum optics and enabled precise control and readout of artificial atoms, with major consequences for quantum information science.",
        "attribution": "Blais developed key theoretical foundations, while Schoelkopf and Wallraff led pivotal experimental demonstrations and established the platform.",
        "maturity": "The architecture is experimentally mature, reproducible and central to ongoing quantum-computing development.",
        "uncertainties": [
          "The proposed discovery encompasses a broad sequence of theoretical and experimental advances, so the award's boundary would need to be defined."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made controlled quantum many-body experiments possible, including clean studies of lattice models and the transition to a Mott insulator.",
        "attribution": "Bloch and Greiner were central to landmark experimental demonstrations; Zoller helped establish the theoretical vision for using trapped atoms as a quantum simulator.",
        "maturity": "The platform has been independently developed and expanded over many years, and its principal capabilities are firmly established.",
        "uncertainties": [
          "Credit spans a large international community, and the proposed framing combines the general simulation platform with particular landmark results."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Jairo Sinova",
        "Libor Šmejkal",
        "Tomas Jungwirth"
      ],
      "assessment": {
        "nobel_worthiness": "Altermagnetism proposes a distinct form of collinear magnetic order with compensated magnetization and spin-split electronic bands, potentially broadening the materials basis of spintronics.",
        "attribution": "The credited theorists have been prominent in formulating, identifying and promoting the classification and its consequences.",
        "maturity": "The concept is recent and experimental identification is developing; it is not yet as settled as established magnetic phases.",
        "uncertainties": [
          "The boundaries between altermagnets and previously known compensated magnetic materials, and the extent of decisive experimental confirmation, remain open."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Kin Fai Mak",
        "Long Ju",
        "Xiaodong Xu"
      ],
      "assessment": {
        "nobel_worthiness": "Fractional quantum anomalous Hall states in graphene-based materials could provide an important route to studying strongly correlated topological phases without an applied magnetic field.",
        "attribution": "The credited researchers led prominent experimental demonstrations in related moiré and rhombohedral graphene platforms.",
        "maturity": "The results are recent, scientifically important and developing, but require time for independent confirmation and a stable account of the distinct material realizations.",
        "uncertainties": [
          "The long-term robustness, reproducibility and relationship among the reported fractional states are not yet established."
        ]
      }
    }
  ]
